mapper.select:
select f.id, f.target_type, f.target_id, f.create_time, case f.target_type when 'city' then c.name when 'attraction' then a.name when 'guide' then g.title when 'trip' then null end as target_title, case f.target_type when 'city' then c.cover_image when 'attraction' then a.cover_image when 'guide' then g.cover_image when 'trip' then null end as target_cover_image, case f.target_type when 'guide' then g.summary else null end as target_summary from voya_ai_favorite f left join voya_ai_city c on f.target_type = 'city' and f.target_id = c.id and c.del_flag = '0' left join voya_ai_attraction a on f.target_type = 'attraction' and f.target_id = a.id and a.del_flag = '0' left join voya_ai_guide g on f.target_type = 'guide' and f.target_id = g.id and g.del_flag = '0' where f.user_id = #{userId}
and f.target_type = #{targetType}
order by f.create_time desc

mapper.update:
update voya_ai_attraction
set favorite_count = greatest(0, ifnull(favorite_count, 0) + #{delta})
where id = #{targetId}

update voya_ai_guide
set favorite_count = greatest(0, ifnull(favorite_count, 0) + #{delta})
where id = #{targetId}

mapper.select:
select f.id, f.user_id, f.target_type, f.target_id, f.create_time, u.nickname, u.avatar_url, case f.target_type when 'city' then c.name when 'attraction' then a.name when 'guide' then g.title when 'trip' then null end as target_title, case f.target_type when 'city' then c.cover_image when 'attraction' then a.cover_image when 'guide' then g.cover_image when 'trip' then null end as target_cover_image, case f.target_type when 'guide' then g.summary else null end as target_summary from voya_ai_favorite f left join voya_ai_user u on f.user_id = u.id left join voya_ai_city c on f.target_type = 'city' and f.target_id = c.id and c.del_flag = '0' left join voya_ai_attraction a on f.target_type = 'attraction' and f.target_id = a.id and a.del_flag = '0' left join voya_ai_guide g on f.target_type = 'guide' and f.target_id = g.id and g.del_flag = '0'
and f.target_type = #{targetType}
and u.nickname like concat('%', #{nickname}, '%')
and f.create_time >= #{beginCreateTime}
and f.create_time < date_add(#{endCreateTime}, interval 1 day)
order by f.create_time desc, f.id desc
